  "statements": [
    {
      "statement": "After fording, items found contaminated should be cleaned.",
      "answer_quote": "After fording, any items found contaminated should be cleaned"
    },
    {
      "statement": "After fording, items found contaminated should be inspected for damage or corrosion.",
      "answer_quote": "inspected for damage or corrosion"
    },
    {
      "statement": "After fording, contaminated components such as differentials and geared hubs must be cleaned thoroughly with appropriate solvents and then dried before reassembly.",
      "answer_quote": "Contaminated components, such as differentials and geared hubs, must be cleaned thoroughly using appropriate solvents and then dried before reassembly"
    },
    {
      "statement": "After fording, cleaning and drying contaminated components before reassembly is intended to prevent internal damage or premature wear.",
      "answer_quote": "before reassembly to prevent internal damage or premature wear"
    },
    {
      "statement": "After fording contamination, 1.5 quarts of gear oil are typically recommended to refill each axle differential.",
      "answer_quote": "For each axle differential: 1.5 quarts of gear oil are typically recommended for refill after fording contamination"
    },
    {
      "statement": "After fording contamination, 0.5 quarts of gear oil are recommended to refill each geared hub.",
      "answer_quote": "For each geared hub: 0.5 quarts of gear oil are recommended for refill"
    },
    {
      "statement": "The stated refill quantities are consistent with typical HMMWV (M998-series) maintenance practices.",
      "answer_quote": "are consistent with typical HMMWV (M998-series) maintenance practices"
    }
  ],
  "excluded_metadata": [
